using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Collections.Concurrent;using System.Reflection;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Security.Cryptography;
using UnityEngine;using Verse;using RimWorld;using Newtonsoft.Json;using WarEconomy.WorkerBridge;
namespace QASemantic {
 [StaticConstructorOnStartup] public static class Boot {static Boot(){new HarmonyLib.Harmony("qa.semanticgate.faults").PatchAll();var g=new GameObject("QA RoundTrip Read Observer");UnityEngine.Object.DontDestroyOnLoad(g);g.AddComponent<Observer>();}}
 public class Observer:MonoBehaviour {
  const BindingFlags BF=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
  class Request {public string text;public TaskCompletionSource<string> done=new TaskCompletionSource<string>();}
  ConcurrentQueue<Request> queue=new ConcurrentQueue<Request>();TcpListener listener;bool running=true;
  void Awake(){string val;int port=30980;if(GenCommandLine.TryGetCommandLineArg("sgqaport",out val))int.TryParse(val,out port);listener=new TcpListener(IPAddress.Loopback,port);listener.Start();new Thread(()=>{while(running){try{var c=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(_=>Client(c));}catch{break;}}}){IsBackground=true}.Start();}
  void Client(TcpClient c){using(c)using(var s=c.GetStream())using(var rd=new StreamReader(s))using(var w=new StreamWriter(s,new UTF8Encoding(false)){AutoFlush=true}){try{string l;while((l=rd.ReadLine())!=null){var q=new Request{text=l};queue.Enqueue(q);if(q.done.Task.Wait(60000)){w.WriteLine(q.done.Task.Result);w.WriteLine("---END---");}}}catch{}}}
  void Update(){Request q;if(!queue.TryDequeue(out q))return;try{var p=q.text.Split(new[]{' '},2);object value;if(p[0]=="SNAP")value=Snapshot();else if(p[0]=="CENSUS")value=EngineHostCensus.GenerateCensus(Find.Maps[0]);else if(p[0]=="COMPAREPAIR"){var pair=JsonConvert.DeserializeObject<Dictionary<string,CensusManifestData>>(File.ReadAllText(p[1]));value=EngineHostCensus.CompareCensus(pair["expected"],pair["actual"]);}else if(p[0]=="COMPARE"){var expected=JsonConvert.DeserializeObject<CensusManifestData>(File.ReadAllText(p[1]));value=EngineHostCensus.CompareCensus(expected,EngineHostCensus.GenerateCensus(Find.Maps[0]));}else if(p[0]=="MUTATE")value=Mutations.Apply(p[1]);else if(p[0]=="ARM")value=Mutations.Arm(p[1]);else if(p[0]=="RESERVATIONS")value=Mutations.Reservations();else if(p[0]=="META")value=Mutations.Meta();else if(p[0]=="JOB")value=StartJob();else value=new{error="unknown"};q.done.TrySetResult(JsonConvert.SerializeObject(value));}catch(Exception e){q.done.TrySetResult(JsonConvert.SerializeObject(new{error=e.ToString()}));}}
  static object Get(object o,string name){if(o==null)return null;for(var t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(name,BF|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(o);var p=t.GetProperty(name,BF|BindingFlags.DeclaredOnly);if(p!=null&&p.GetIndexParameters().Length==0){try{return p.GetValue(o,null);}catch{return null;}}}return null;}
  static string Ref(object o){if(o==null)return "";if(o is Thing)return ((Thing)o).ThingID;if(o is Def)return ((Def)o).defName;if(o is ILoadReferenceable)return ((ILoadReferenceable)o).GetUniqueLoadID();return o.ToString();}
  static Dictionary<string,object> Fields(object o){var d=new Dictionary<string,object>();if(o==null)return d;for(var t=o.GetType();t!=null&&t!=typeof(object);t=t.BaseType)foreach(var f in t.GetFields(BF|BindingFlags.DeclaredOnly)){if(f.IsStatic)continue;object v;try{v=f.GetValue(o);}catch{continue;}if(v==null||v is string||v.GetType().IsPrimitive||v.GetType().IsEnum||v is decimal)d[f.Name]=v;else if(v is Thing||v is Def||v is ILoadReferenceable)d[f.Name]=Ref(v);}return d;}
  static List<string> Refs(object value){var a=new List<string>();if(value is IEnumerable)foreach(var v in (IEnumerable)value)a.Add(Ref(v));return a.OrderBy(x=>x).ToList();}
  static List<Thing> Spawned(Map m){var v=Get(m,"spawnedThings") as IEnumerable;return v==null?m.listerThings.AllThings.ToList():v.Cast<object>().OfType<Thing>().ToList();}
  static Dictionary<string,object> PawnData(Pawn p){var d=new Dictionary<string,object>();d["skills"]=p.skills?.skills.Select(s=>new{def=s.def.defName,level=s.Level,xp=s.xpSinceLastLevel,passion=s.passion.ToString()}).OrderBy(s=>s.def).ToList();d["hediffs"]=p.health?.hediffSet.hediffs.Select(h=>new{id=h.GetUniqueLoadID(),def=h.def.defName,part=h.Part?.Label,severity=h.Severity,fields=Fields(h)}).OrderBy(h=>h.id).ToList();d["equipment"]=p.equipment?.AllEquipmentListForReading.Select(x=>x.ThingID).OrderBy(x=>x).ToList();d["apparel"]=p.apparel?.WornApparel.Select(x=>x.ThingID).OrderBy(x=>x).ToList();d["inventory"]=p.inventory?.innerContainer.Select(x=>new{id=x.ThingID,def=x.def.defName,count=x.stackCount}).OrderBy(x=>x.id).ToList();d["ownedBed"]=Ref(p.ownership?.OwnedBed);d["master"]=Ref(p.playerSettings?.Master);d["followDrafted"]=p.playerSettings?.followDrafted;d["followFieldwork"]=p.playerSettings?.followFieldwork;d["relations"]=p.relations?.DirectRelations.Select(x=>new{def=x.def.defName,other=Ref(x.otherPawn),otherMap=x.otherPawn.MapHeld?.uniqueID}).OrderBy(x=>x.other).ToList();d["job"]=p.CurJob==null?null:new{def=p.CurJob.def.defName,targetA=p.CurJob.targetA.ToString(),targetB=p.CurJob.targetB.ToString(),fields=Fields(p.CurJob)};d["bio"]=p.ageTracker?.AgeBiologicalTicks;d["chrono"]=p.ageTracker?.AgeChronologicalTicks;d["food"]=p.needs?.food?.CurLevel;d["rest"]=p.needs?.rest?.CurLevel;d["royalty"]=Fields(p.royalty);d["ideology"]=Ref(Get(p.ideo,"Ideo"));return d;}
  static object Snapshot(){var errors=new List<string>();var maps=new List<object>();foreach(var m in Find.Maps){var entities=new SortedDictionary<string,object>();var seen=new HashSet<Thing>();var duplicateIds=new List<string>();Action<Thing,string> visit=null;visit=(t,holder)=>{if(t==null||!seen.Add(t))return;try{var d=new Dictionary<string,object>{{"id",t.ThingID},{"def",t.def.defName},{"class",t.GetType().FullName},{"category",t.def.category.ToString()},{"stack",t.stackCount},{"hp",t.HitPoints},{"pos",t.Position.ToString()},{"rot",t.Rotation.AsInt},{"stuff",t.Stuff?.defName},{"faction",Ref(t.Faction)},{"holder",holder},{"fields",Fields(t)}};if(t is Pawn){var p=(Pawn)t;d["pawn"]=PawnData(p);if(p.equipment!=null)foreach(var x in p.equipment.AllEquipmentListForReading)visit(x,t.ThingID+"/equipment");if(p.apparel!=null)foreach(var x in p.apparel.WornApparel)visit(x,t.ThingID+"/apparel");if(p.inventory!=null)foreach(var x in p.inventory.innerContainer)visit(x,t.ThingID+"/inventory");visit(p.carryTracker?.CarriedThing,t.ThingID+"/carry");}if(t is MinifiedThing)visit(((MinifiedThing)t).InnerThing,t.ThingID+"/minified");if(t is Corpse)visit(((Corpse)t).InnerPawn,t.ThingID+"/corpse");if(t is IThingHolder){var held=((IThingHolder)t).GetDirectlyHeldThings();if(held!=null)foreach(var x in held)visit(x,t.ThingID+"/direct");}if(t is Building_WorkTable)d["bills"]=((Building_WorkTable)t).BillStack.Bills.Select(b=>new{id=b.GetUniqueLoadID(),type=b.GetType().FullName,fields=Fields(b)}).OrderBy(b=>b.id).ToList();if(t is ThingWithComps){var tc=(ThingWithComps)t;d["comps"]=tc.AllComps.Select(c=>new{type=c.GetType().FullName,fields=Fields(c)}).ToList();var power=tc.TryGetComp<CompPower>();if(power!=null)d["power"]=new{fields=Fields(power),netMembers=Refs(Get(power.PowerNet,"powerComps")),connections=Refs(Get(power,"connectChildren"))};var assigned=tc.TryGetComp<CompAssignableToPawn>();if(assigned!=null)d["assignedPawns"]=assigned.AssignedPawnsForReading.Select(p=>p.ThingID).OrderBy(x=>x).ToList();}if(entities.ContainsKey(t.ThingID))duplicateIds.Add(t.ThingID);entities[t.ThingID]=d;}catch(Exception ex){errors.Add(t.ThingID+":"+ex.Message);}};foreach(var t in Spawned(m))visit(t,"map:"+m.uniqueID);var zone=m.zoneManager.AllZones.Select(z=>new{id=z.ID,type=z.GetType().FullName,cells=z.Cells.Select(c=>c.ToString()).OrderBy(x=>x).ToList(),fields=Fields(z)}).OrderBy(z=>z.id).ToList();var des=m.designationManager.AllDesignations.Select(d=>new{def=d.def.defName,target=d.target.ToString()}).OrderBy(d=>d.def+":"+d.target).ToList();var cond=m.gameConditionManager.ActiveConditions.Select(c=>new{def=c.def.defName,id=c.uniqueID,duration=c.Duration,fields=Fields(c)}).OrderBy(c=>c.id).ToList();var reservations=Get(m.reservationManager,"reservations") as IEnumerable;maps.Add(new{mapId=m.uniqueID,tile=m.Tile.ToString(),parent=Ref(m.Parent),entities,duplicateIds,zones=zone,designations=des,conditions=cond,weather=Fields(m.weatherManager),mapComponents=Refs(Get(m,"components")),reservations=reservations?.Cast<object>().Select(x=>new{type=x.GetType().FullName,fields=Fields(x)}).ToList()});}
   var assemblies=AppDomain.CurrentDomain.GetAssemblies().Where(a=>a.GetName().Name.Contains("WarEconomy")||a.GetName().Name=="QA.SemanticGate.Observer"||a.GetName().Name=="Assembly-CSharp").Select(a=>new{name=a.GetName().Name,path=a.Location,mvid=a.ManifestModule.ModuleVersionId.ToString(),sha=Hash(a.Location)}).ToList();var rm=Find.ResearchManager;var progress=Get(rm,"progress") as IDictionary;var research=new SortedDictionary<string,object>();if(progress!=null)foreach(DictionaryEntry e in progress)research[Ref(e.Key)]=e.Value;return new{pid=System.Diagnostics.Process.GetCurrentProcess().Id,version=VersionControl.CurrentVersionStringWithRev,ticksGame=Find.TickManager.TicksGame,ticksAbs=Find.TickManager.TicksAbs,maps,assemblies,errors,research,gameComponents=Refs(Get(Current.Game,"components")),worldComponents=Refs(Get(Current.Game.World,"components")),worldObjects=Current.Game.World.worldObjects.AllWorldObjects.Select(w=>new{id=w.GetUniqueLoadID(),type=w.GetType().FullName,tile=w.Tile.ToString()}).ToList(),factions=Find.FactionManager.AllFactions.Select(f=>new{id=f.GetUniqueLoadID(),def=f.def.defName}).ToList(),worldPawns=Refs(Get(Find.WorldPawns,"AllPawnsAliveOrDead")),ideologies=Refs(Get(Find.IdeoManager,"IdeosListForReading")),quests=Refs(Get(Find.QuestManager,"QuestsListForReading"))};
  }
  static string Hash(string path){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(File.ReadAllBytes(path))).Replace("-","");}
  static object StartJob(){var map=Find.Maps[0];var p=map.mapPawns.AllPawns.First(x=>x.ThingID=="Human302");var candidates=GenRadial.RadialCellsAround(p.Position,12,true).Where(c=>c.InBounds(map)&&c.Standable(map)&&c.DistanceTo(p.Position)>6).ToList();var cell=candidates.First();var job=JobMaker.MakeJob(JobDefOf.Goto,cell);p.jobs.TryTakeOrderedJob(job);var method=map.reservationManager.GetType().GetMethods().First(x=>x.Name=="Reserve");var args=method.GetParameters().Select(x=>x.ParameterType==typeof(Pawn)?(object)p:x.ParameterType==typeof(Verse.AI.Job)?job:x.ParameterType==typeof(LocalTargetInfo)?new LocalTargetInfo(cell):x.ParameterType==typeof(int)?(x.Name=="stackCount"?-1:1):x.ParameterType==typeof(bool)?false:x.HasDefaultValue?x.DefaultValue:null).ToArray();var reserved=method.Invoke(map.reservationManager,args);return new{pawn=p.ThingID,cell=cell.ToString(),job=p.CurJob?.def.defName,reserved,parameters=method.ToString()};}
  void OnDestroy(){running=false;try{listener?.Stop();}catch{}}
 }
}
